#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: off-site backups to Scaleway Object Storage (#17).
# Run it on your own computer after deploy/setup-wizard.sh has set the server up. It does the typing on the server over
# ssh; you do the clicking in Scaleway's console. Secrets (the bucket key, the encryption password) go from your
# keyboard to the server and are never written on this computer. The one file kept here holds non-secret answers
# (ENV_FILE below, shared with the setup wizard, so it already knows the server's address and your key).
# ──────────────────────────────────────────────────────────────────────────

DEPLOY_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ENV_FILE="${ENV_FILE:-$DEPLOY_DIR/.env.server-setup}" # ignored by git (.env.*); answers that are not secret
APP_USER="wordwright"
REMOTE_DIR="wordwright" # under the app user's home
RCLONE_IMAGE=$(grep '^RCLONE_IMAGE=' "$DEPLOY_DIR/offsite.sh" | cut -d'"' -f2) # one place pins the version

# One ssh connection is kept open for ten minutes, so a passphrase is asked once. The server's host key is checked
# against ~/.ssh/known_hosts, where the setup wizard put it (no trust-on-first-use).
CTL_DIR=$(mktemp -d /tmp/wwXXXXXX)
_close_connections() {
  local s
  for s in "$CTL_DIR"/*; do [[ -S "$s" ]] && ssh -o "ControlPath=$s" -O exit wordwright-offsite >/dev/null 2>&1; done
  rm -rf "$CTL_DIR"
  return 0
}
trap _close_connections EXIT
_sshopts() {
  SSHO=(-i "$SSH_KEY" -o IdentitiesOnly=yes -o StrictHostKeyChecking=yes -o ControlMaster=auto -o ControlPersist=10m
    -o "ControlPath=$CTL_DIR/%C")
}
ssh_app() { _sshopts; ssh "${SSHO[@]}" "$APP_USER@$SERVER_IP" "$@"; }
ssh_app_tty() { _sshopts; ssh -t "${SSHO[@]}" "$APP_USER@$SERVER_IP" "$@"; }
scp_app() { _sshopts; scp "${SSHO[@]}" "$@"; }

run_wizard() {

TOTAL_STAGES=7

banner "Wordwright: encrypted off-site backups in Scaleway"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Connect to the server"
say "Every night the server copies its database backup to a private bucket at Scaleway, encrypted first, so that"
say "losing the server (or the whole UpCloud account) does not lose the backups."
SERVER_IP=$(_existing SERVER_IP || true)
SSH_KEY=$(_existing SSH_KEY || true)
[[ -n "$SERVER_IP" && -n "$SSH_KEY" ]] || { warn "Run deploy/setup-wizard.sh first: it records the server's address and your key."; exit 1; }
say "Server $SERVER_IP, key $SSH_KEY"
ssh_app "docker --version" >/dev/null || { warn "Could not log in to the server as $APP_USER."; exit 1; }
say "✓ logged in"
scp_app "$DEPLOY_DIR/backup.sh" "$DEPLOY_DIR/offsite.sh" "$DEPLOY_DIR/rollback.sh" "$APP_USER@$SERVER_IP:$REMOTE_DIR/"
ssh_app "chmod +x $REMOTE_DIR/*.sh"
say "✓ the latest backup scripts are on the server"
pause "Press Enter."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Scaleway: a separate project for the backups"
say "A project of its own means the key the server holds can only ever reach the backups, nothing else you have at Scaleway."
open_url "https://console.scaleway.com/organization/projects"
step "Create a project named wordwright-backups."
step "Make it the project you are working in (the project picker at the top left of the console)."
note "Scaleway's console may look different from this description; follow the intent."
pause "Done? Press Enter."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Scaleway: the bucket"
open_url "https://console.scaleway.com/object-storage/buckets"
suggestion="wordwright-backups-$(openssl rand -hex 3)"
step "Create a bucket in the wordwright-backups project:"
step "  • name: it must be unique across all of Scaleway, so something like $suggestion"
step "  • region: Paris (fr-par) unless you have a reason to choose another"
step "  • visibility: Private"
step "  • storage: Standard Multi-AZ. Leave the size boxes at 0 (they only feed a cost estimate; you pay for what you use,"
step "    a few cents a month here). Not Glacier: it is archive storage, slow and costly to get back from."
step "Open the bucket's settings and switch Versioning on (a deleted or overwritten backup can then be recovered)."
step "Lifecycle rules (a separate page from the bucket form): add a rule for all objects:"
step "  • expire the current version after 30 days"
step "  • non-current versions: 'Days after versions become non-current' = 7, and 'Non-current versions to retain' = 0"
step "    (any number above 0 would keep deleted backups for ever)"
step "  • expire delete markers that have no non-current versions, if that is offered"
note "That keeps about a month of backups. A deleted account's data can stay in them for up to about 37 days; the data map (#320) says so."
pause "Bucket created, private, with versioning and the rule? Press Enter."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Scaleway: a key for the server, for this project only"
open_url "https://console.scaleway.com/iam/applications"
step "Create an application named wordwright-backup."
step "Give it a policy: permission set ObjectStorageFullAccess, scoped to the project wordwright-backups only."
step "Create an API key for that application (preferred project: wordwright-backups). Copy the access key and the secret key;"
step "the secret key is shown only once."
note "This is a different key from the one the app uses to send email. Each reaches only what it needs."
printf '\n'
ask BACKUP_BUCKET "Bucket name:"
ask BACKUP_REGION "Bucket region (for example fr-par):"
ask BACKUP_ACCESS_KEY "Access key (starts SCW):"
write_env BACKUP_BUCKET "$BACKUP_BUCKET"
write_env BACKUP_REGION "$BACKUP_REGION"
ask_secret BACKUP_SECRET_KEY "Secret key (hidden):"
[[ -n "$BACKUP_SECRET_KEY" ]] || { warn "No secret key entered."; exit 1; }

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Encrypt the backups before they leave the server"
say "The backups hold writers' work. They are encrypted on the server with a password and a salt before upload, file"
say "names included, so the bucket (and Scaleway) hold nothing readable."
if confirm "Is this the first time? (make a new password and salt; answer no only when rebuilding a server and restoring old backups)"; then
  CRYPT_PASSWORD=$(openssl rand -base64 36 | tr -d '\n')
  CRYPT_SALT=$(openssl rand -base64 36 | tr -d '\n')
  printf '\n'
  warn "Save BOTH in your password manager now, as 'Wordwright backup encryption: password and salt'."
  say "Without them the backups cannot be opened by anyone, including you. They are not stored anywhere else."
  printf '\n    password: %s%s%s\n    salt:     %s%s%s\n\n' "$BOLD" "$CRYPT_PASSWORD" "$RESET" "$BOLD" "$CRYPT_SALT" "$RESET"
  until confirm "Saved in your password manager?"; do say "Please save them first."; done
else
  ask_secret CRYPT_PASSWORD "The existing password (hidden):"
  ask_secret CRYPT_SALT "The existing salt (hidden):"
fi
# rclone wants the two obscured (a reversible scrambling, not security: the file stays mode 600 on the server).
obscure() { printf '%s' "$1" | ssh_app "docker run --rm -i $RCLONE_IMAGE obscure -" 2>/dev/null | tr -d '\n'; }
obscured_password=$(obscure "$CRYPT_PASSWORD")
obscured_salt=$(obscure "$CRYPT_SALT")
[[ -n "$obscured_password" && -n "$obscured_salt" ]] || { warn "Could not prepare the encryption settings on the server."; exit 1; }
{
  printf 'RCLONE_CONFIG_SCW_TYPE=s3\n'
  printf 'RCLONE_CONFIG_SCW_PROVIDER=Scaleway\n'
  printf 'RCLONE_CONFIG_SCW_ACCESS_KEY_ID=%s\n' "$BACKUP_ACCESS_KEY"
  printf 'RCLONE_CONFIG_SCW_SECRET_ACCESS_KEY=%s\n' "$BACKUP_SECRET_KEY"
  printf 'RCLONE_CONFIG_SCW_ENDPOINT=s3.%s.scw.cloud\n' "$BACKUP_REGION"
  printf 'RCLONE_CONFIG_SCW_REGION=%s\n' "$BACKUP_REGION"
  printf 'RCLONE_CONFIG_SCW_ACL=private\n'
  # The bucket exists already: never let rclone create one (a typo in the name would otherwise make a stray bucket).
  printf 'RCLONE_CONFIG_SCW_NO_CHECK_BUCKET=true\n'
  printf 'RCLONE_CONFIG_OFFSITE_TYPE=crypt\n'
  printf 'RCLONE_CONFIG_OFFSITE_REMOTE=scw:%s\n' "$BACKUP_BUCKET"
  printf 'RCLONE_CONFIG_OFFSITE_PASSWORD=%s\n' "$obscured_password"
  printf 'RCLONE_CONFIG_OFFSITE_PASSWORD2=%s\n' "$obscured_salt"
  printf 'RCLONE_CONFIG_OFFSITE_FILENAME_ENCRYPTION=standard\n'
  printf 'RCLONE_CONFIG_OFFSITE_DIRECTORY_NAME_ENCRYPTION=true\n'
} | ssh_app "cd $REMOTE_DIR && umask 077 && cat > offsite.env.tmp && mv offsite.env.tmp offsite.env && chmod 600 offsite.env"
unset CRYPT_PASSWORD CRYPT_SALT BACKUP_SECRET_KEY obscured_password obscured_salt
say "✓ settings written to ~/$REMOTE_DIR/offsite.env on the server (mode 600)"
pause "Press Enter."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Try it: back up, upload, and read it back"
say "This makes a backup now, uploads it encrypted, lists it, then downloads it again and checks the database is intact."
ssh_app_tty "cd $REMOTE_DIR && ./backup.sh" || { warn "The upload failed. The message above says why: a 403 means the key or the policy, a 404 the bucket name or region."; exit 1; }
printf '\n'
say "As the server sees it (real names):"
ssh_app "cd $REMOTE_DIR && ./offsite.sh list"
say "As Scaleway holds it (scrambled; there should be nothing readable):"
ssh_app "cd $REMOTE_DIR && docker run --rm -e RCLONE_LOG_LEVEL=ERROR --env-file offsite.env $RCLONE_IMAGE lsf SCW:$BACKUP_BUCKET --max-depth 1 | head -5"
printf '\n'
ssh_app_tty "cd $REMOTE_DIR && ./offsite.sh verify"
pause "You should see 'integrity: ok'. Press Enter."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "The nightly run does it too"
say "The nightly timer runs the same backup.sh, so it now uploads as well. Running it once through the timer's own unit:"
ssh_app "sudo systemctl start wordwright-backup.service; systemctl show -p Result -p ExecMainStatus wordwright-backup.service"
note "Result=success means it worked as the timer will run it at 02:30."
ssh_app "systemctl list-timers wordwright-backup.timer --no-pager | head -3"
open_url "https://console.scaleway.com/object-storage/buckets"
step "In the console, open the bucket and check the lifecycle rule and versioning are on."
SKIPPED+=("Practise a restore from Scaleway once: docs/deploy.md, 'Restoring from the off-site copy'")
SKIPPED+=("Keep the encryption password and salt, and KEY_ENCRYPTION_SECRET, in your password manager")

finish
}

run_wizard "$@"; exit
